-- v0.84.0: os recursos que o app já tinha e a lista de Recursos da
-- Administração não: servidores MCP, skills, busca no skills.sh, agente Kilo
-- Code, OpenRouter e LiteLLM, e a busca na conversa. Entram em todo plano
-- opcionais e ligados, como o usuário já os tem hoje; o admin tira dos planos
-- que quiser.

on conflict (key) do nothing;

select p.key, f.key, 'optional', true from public.plans p cross join public.features f
where f.key in ('mcp', 'skills', 'skillsHub', 'kiloCode', 'gatewayProviders', 'conversationFind')
on conflict (plan_key, feature_key) do nothing;

on conflict (locale, key) do update set value = excluded.value;
